import { IWeatherRepository } from '@src/domain/interfaces/weather';
import { Weather } from '../../../domain/entities/weather';
import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { GetWeatherQuery } from '@src/application/weather/queries/get_weather/get_weather_query';
import { HttpService } from '@core/service';
import { WEATHER_BASE_URL } from '@src/config';

@injectable()
export class WeatherRepository
  extends HttpService
  implements IWeatherRepository
{
  constructor() {
    super({ baseURL: WEATHER_BASE_URL });
  }

  async getWeather<TParameter>(query: Query<TParameter>): Promise<Weather> {
    const request = query.query as unknown as GetWeatherQuery;
    const url = '/v1/forecast';
    const params = {
      latitude: String(request.latitude),
      longitude: String(request.longitude),
      current_weather: 'true',
    };

    const response = await this.get<{ current_weather: any }>(url, {
      params: params,
    });

    return this.parseWeather(response.data?.current_weather);
  }

  private parseWeather(data: any): Weather {
    return {
      temperature: Number(data.temperature),
      windspeed: Number(data.windspeed),
      winddirection: Number(data.winddirection),
      weathercode: Number(data.weathercode),
      time: String(data.time),
    };
  }
}
