import React, { useState } from 'react';
import { Keyboard, KeyboardAvoidingView, TextInput, View } from 'react-native';
import { useTheme, Text, GradientButton } from '@core/ui';
import SliderProgress from '../slider/Slider';
import useCSS from '@src/presentation/style';
import { IS_IOS } from '@core/service';

interface Props {
    onSubmit?: (value: number) => void;
    min: number;
    max: number;
    value: number;
}

const MonthSlider = (props: Props) => {
    const { theme } = useTheme();
    const css = useCSS();
    const { onSubmit, min, max, value } = props;
    const [displayValue, setDisplayValue] = useState(value);

    const handleSubmit = () => {
        Keyboard.dismiss();
        let value = displayValue;
        if (value < min) {
            value = min;
        }
        onSubmit?.(value);
    }
    const handleChangeMonth = (value: number) => {
        if (Number.isNaN(value)) return;
        if (value > max) {
            setDisplayValue(max)
        } else {
            setDisplayValue(value);
        }
    }
    return (
        <View>
            <KeyboardAvoidingView behavior={IS_IOS ? 'padding' : 'height'} style={[css.flex_1]}>
                <View style={[css.row, css.flex_1, css.justify_end, css.items_center, { height: theme.Size.Vertical.Jumbo, gap: theme.Size.Horizontal.Base }]} >
                    <View style={[css.flex_1]}>
                        <SliderProgress min={min} max={max} onChange={(text: number) => { setDisplayValue(text) }} value={displayValue} />
                        <View style={[css.row, css.justify_between]}>
                            <Text style={theme.Typography.TextSubheadline.Regular}>{min} năm</Text>
                            <Text style={theme.Typography.TextSubheadline.Regular}>{max} năm</Text>
                        </View>
                    </View>
                    <View style={[css.p_regular, css.rounded_base, css.justify_between, { borderWidth: 1, borderColor: theme.Colors.Border.Neutral400, width: theme.Size.Horizontal.Huge }]}>
                        <TextInput style={[css.text_center, css.text_subheadline, { paddingVertical: 0 }]} value={String(displayValue)} onChangeText={(value: string) => handleChangeMonth(Number(value))} keyboardType='numeric' />
                    </View>
                </View>
                <GradientButton gradientProps={{ type: 'primary' }} title='Lưu' style={{ marginTop: theme.Size.Vertical.Medium }} onPress={handleSubmit} />
            </KeyboardAvoidingView>
        </View>
    );
};

export default MonthSlider;
