import { TYPES } from '@src/di/types/types';
import { inject } from 'inversify';
import { ResendOTPPayload } from './resend_otp_query';
import type { IResendOTPRepository } from '@src/domain/interfaces/loan_collateral/resend_otp';

export class ResendOTPHandler {
    private readonly _resendOTPRepository: IResendOTPRepository;

    constructor(@inject(TYPES.IResendOTPRepository) resendOTPRepository: IResendOTPRepository) {
        this._resendOTPRepository = resendOTPRepository;
    }

    handle(dataReq: ResendOTPPayload) {
        return this._resendOTPRepository.resendOTP(dataReq);
    }
}
